static void committedAt(String event,IssueTimelineR30.Stage stage,long wall,long mono,String clock){
    if(event==null||stage!=IssueTimelineR30.Stage.SETTLED&&stage!=IssueTimelineR30.Stage.NEXT_FROZEN)return;
